import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';
import { GenericException } from '../system';

export class BootstrapException extends BaseException {
    constructor(gameName: string, message: string, error?: Error) {
        super('Exception.Bootstrap', `Failed to bootstrap ${gameName}: ${message}`);

        if (error) {
            error.name = error.name || 'Exception.Bootstrap.Error';
            this.innerException = new GenericException(error.name, error.message, error.stack);
        }
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
